import{_ as t,o,c as a,al as n}from"./chunks/framework.CAAkqCQG.js";const g=JSON.parse('{"title":"Introduction","description":"What lognal is, why it draws logs on a canvas, what it can do, and which browsers it supports.","frontmatter":{"order":1,"description":"What lognal is, why it draws logs on a canvas, what it can do, and which browsers it supports.","head":[["link",{"rel":"canonical","href":"https://lognal.cdget.com/introduction"}],["link",{"rel":"alternate","hreflang":"en","href":"https://lognal.cdget.com/introduction"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://lognal.cdget.com/ko/introduction"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://lognal.cdget.com/introduction"}],["meta",{"property":"og:title","content":"Introduction | lognal"}],["meta",{"property":"og:description","content":"What lognal is, why it draws logs on a canvas, what it can do, and which browsers it supports."}],["meta",{"property":"og:url","content":"https://lognal.cdget.com/introduction"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Introduction | lognal"}],["meta",{"name":"twitter:description","content":"What lognal is, why it draws logs on a canvas, what it can do, and which browsers it supports."}]]},"headers":[],"relativePath":"introduction.md","filePath":"en/introduction.md","lastUpdated":1789298872000}'),r={name:"introduction.md"};function s(i,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>lognal is a log viewer for web pages that looks and works like a terminal. It draws log output on a canvas, so it keeps up with a fast stream of messages and a long history without slowing the page down.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><ul><li><strong>Mirror the console.</strong> Record <code>console.log</code>, <code>console.warn</code>, <code>console.table</code>, <code>console.group</code> and the other console methods, and show them the way browser developer tools do. The original console keeps working. See <a href="/guide/console">Console capture</a>.</li><li><strong>Show typed values.</strong> Objects, arrays, <code>Map</code>, <code>Set</code>, errors and DOM elements are captured when they are logged and open and close with a click. See <a href="/guide/values">Typed values</a>.</li><li><strong>Read text files.</strong> Read a log file in chunks, detect its encoding, and turn ANSI escape codes into colors. In Chromium browsers, lognal can also follow a file that keeps growing. See <a href="/guide/text-files">Text files</a>.</li><li><strong>Work like a log viewer.</strong> A toolbar follows new logs, clears the log, scrolls to the top or bottom, turns wrapping on and off, and filters by text and level. Ctrl+F searches the log and highlights every match without hiding anything. A status bar counts entries, each entry can show a timestamp, and text can be selected and copied, or copied a whole entry at a time from the menu of that entry. Addresses in the log are links that open in a new tab, after a confirmation by default. In entry mode, whole entries are selected with Ctrl, Cmd and Shift, the way files are, and copied together. See <a href="/guide/viewer">The viewer</a>.</li><li><strong>Accept commands.</strong> An optional input line passes each command to a function you provide and prints the reply. See <a href="/guide/viewer#input-line">Input line</a>.</li><li><strong>Follow your theme.</strong> Light, dark and automatic modes are built in, and every color is a CSS custom property. See <a href="/guide/theming">Themes and fonts</a>.</li><li><strong>Handle Korean and other CJK text.</strong> Wide characters take two cells, Hangul words stay together when a line wraps, the input line works with IME composition, and legacy encodings such as EUC-KR are detected. See <a href="/guide/cjk">Korean and CJK text</a>.</li></ul><h2 id="why-a-canvas" tabindex="-1">Why a canvas <a class="header-anchor" href="#why-a-canvas" aria-label="Permalink to &quot;Why a canvas&quot;">​</a></h2><p>A log viewer that creates one DOM element per line gets slower as the history grows. Every element costs memory, style and layout work, and a list of a hundred thousand lines is a large page even when only forty lines are on screen.</p><p>lognal keeps entries as plain data and draws only the rows that are visible. The work is split into three parts:</p><ol><li>A <code>LogStore</code> holds the entries in the order they were added, up to a limit of 10,000 by default. The oldest entries are dropped once the limit is reached.</li><li>A <code>LogLayout</code> turns entries into rows for the current width. It caches measured lines, so most frames reuse the work of earlier ones.</li><li>A renderer draws the visible rows on a <code>&lt;canvas&gt;</code> with the 2D context. Any number of new messages between two animation frames costs one draw.</li></ol><p>The cost of a frame depends on the number of rows on screen, not on the size of the history.</p><p>The browser still does the jobs it does better than a canvas. The log area is a native scroll container, so the mouse wheel, touch and keyboard scrolling work as usual. The input line is a real <code>&lt;textarea&gt;</code>, so the browser handles the caret, paste and IME composition. The toolbar is made of real buttons, and a visually hidden list mirrors the visible entries for screen readers.</p><p>Text on a canvas is not part of the page text. The viewer provides its own selection, copy and filter instead: drag to select, press Ctrl+C or Cmd+C to copy, and use the filter in the toolbar to search. The text is laid out on a grid of cells, so the log area needs a monospace font.</p><h2 id="package-contents" tabindex="-1">Package contents <a class="header-anchor" href="#package-contents" aria-label="Permalink to &quot;Package contents&quot;">​</a></h2><p>lognal is one npm package with three entry points. The core has no runtime dependencies. React is an optional peer dependency, needed only for <code>lognal/react</code>.</p><table tabindex="0"><thead><tr><th>Entry point</th><th>Contents</th></tr></thead><tbody><tr><td><code>lognal</code></td><td>The viewer, the store and layout, console capture, text sources and the Canvas 2D renderer</td></tr><tr><td><code>lognal/react</code></td><td>The <code>LogViewer</code> React component, for React 18 or later</td></tr><tr><td><code>lognal/style.css</code></td><td>The layout of the viewer and the light and dark themes</td></tr></tbody></table><h2 id="browser-support" tabindex="-1">Browser support <a class="header-anchor" href="#browser-support" aria-label="Permalink to &quot;Browser support&quot;">​</a></h2><p>lognal targets current versions of Chrome, Edge, Firefox and Safari. The package is compiled to ES2022. A few features depend on newer browser APIs:</p><ul><li><strong>Grapheme clusters.</strong> lognal splits text into user-perceived characters with <code>Intl.Segmenter</code>, available in Chrome 87, Firefox 125 and Safari 14.1. Where it is missing, a built-in fallback joins combining marks, variation selectors, emoji modifiers, zero width joiner sequences and flag pairs to the character before them. <code>setGraphemeSplitter</code> replaces the splitter with your own.</li><li><strong>Following a file.</strong> <code>followTextFile</code> needs a file handle from the File System Access API (<code>showOpenFilePicker</code>). Only Chromium-based browsers provide it, and only on secure pages served over HTTPS or from <code>localhost</code>. <code>readTextFile</code> works in every browser.</li><li><strong>Copying.</strong> <code>copySelection</code> uses the asynchronous Clipboard API on secure pages and falls back to <code>document.execCommand(&#39;copy&#39;)</code> elsewhere.</li><li><strong>IME input on Safari.</strong> Safari up to version 26 fires <code>compositionend</code> before the <code>keydown</code> of the key that commits a composition. The input line accounts for this, so pressing Enter to confirm a Japanese or Chinese candidate does not submit the command.</li></ul>',17)])])}const u=t(r,[["render",s]]);export{g as __pageData,u as default};
